using AssetForge.Core.Models;using AssetForge.Infrastructure.Data;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;namespace AssetForge.Web.Pages;public class CustodyModel(AssetForgeDbContext db):PageModel{public List<AssetAssignment> Active{get;set;}=[];public List<AssetAssignment> History{get;set;}=[];public SelectList Assets{get;set;}=null!;public SelectList People{get;set;}=null!;[BindProperty]public AssetAssignment Input{get;set;}=new();public async Task OnGetAsync(){await Load();}public async Task<IActionResult> OnPostAssignAsync(){if(await db.Assignments.AnyAsync(x=>x.AssetId==Input.AssetId&&x.ReturnedUtc==null)){TempData["Error"]="That asset is already assigned.";return RedirectToPage();}Input.AssignedBy=User.Identity?.Name??"admin";Input.AssignedUtc=DateTime.UtcNow;db.Assignments.Add(Input);var asset=await db.Assets.FindAsync(Input.AssetId);if(asset!=null)asset.Status="Assigned";db.AuditEvents.Add(new AuditEvent{AssetId=Input.AssetId,Action="Assigned",Details=$"Assigned to person ID {Input.PersonId}",PerformedBy=Input.AssignedBy});await db.SaveChangesAsync();return RedirectToPage();}public async Task<IActionResult> OnPostReturnAsync(long id,string returnCondition,string? returnNotes){var row=await db.Assignments.Include(x=>x.Asset).FirstOrDefaultAsync(x=>x.Id==id&&x.ReturnedUtc==null);if(row==null)return RedirectToPage();row.ReturnedUtc=DateTime.UtcNow;row.ReturnCondition=returnCondition;row.ReturnNotes=returnNotes;row.ReturnedBy=User.Identity?.Name??"admin";if(row.Asset!=null)row.Asset.Status=returnCondition=="Damaged"?"Repair":"Available";db.AuditEvents.Add(new AuditEvent{AssetId=row.AssetId,Action="Returned",Details=$"Returned in {returnCondition} condition",PerformedBy=row.ReturnedBy});await db.SaveChangesAsync();return RedirectToPage();}private async Task Load(){Active=await db.Assignments.Include(x=>x.Asset).Include(x=>x.Person).Where(x=>x.ReturnedUtc==null).OrderBy(x=>x.ExpectedReturnUtc).ToListAsync();History=await db.Assignments.Include(x=>x.Asset).Include(x=>x.Person).OrderByDescending(x=>x.AssignedUtc).Take(50).ToListAsync();var busy=await db.Assignments.Where(x=>x.ReturnedUtc==null).Select(x=>x.AssetId).ToListAsync();Assets=new(await db.Assets.Where(x=>!busy.Contains(x.Id)&&x.Status!="Retired").OrderBy(x=>x.AssetTag).Select(x=>new{ x.Id,Name=x.AssetTag+" · "+x.Name}).ToListAsync(),"Id","Name");People=new(await db.People.Where(x=>x.Active).OrderBy(x=>x.FullName).ToListAsync(),"Id","FullName");}}
